const raw = $input.first().json;
const body = (raw.body && typeof raw.body === 'object') ? raw.body : raw;
return [{ json: {
  jobId: body.jobId || '',
  fileUrl: body.fileUrl || '',
  callbackUrl: body.callbackUrl || '',
  callbackSecret: body.callbackSecret || '',
  params: body.params || {},
} }];

const doc = $input.first().json.document || {};
// Homóglifos: o OCR devolve letra grega ou cirílica no lugar da latina, e o que
// sai é texto que parece certo na tela e não casa em regex nenhuma.
//
// O mapa nasceu só com maiúsculas. Faltava justamente o ν minúsculo (U+03BD),
// que é como o OCR lê o "v" datilografado: na matrícula 7.529 do 1º RI de São
// Bernardo, "Av. 2/7529" virou "Aν. 2/7529" em quatro averbações. O parser
// jurídico não reconheceu os cabeçalhos, viu salto na numeração e declarou
// incompleta uma certidão inteira de 7 faces — com o agravante de mandar o
// cliente pedir inteiro teor ao cartório para resolver um erro de leitura.
//
// Só entram caracteres sem uso legítimo em matrícula brasileira. O par
// maiúscula/minúscula não é simétrico de propósito: Ν grego é N latino, mas ν
// minúsculo é v — o critério é o desenho da letra, não o alfabeto.
const HOMOGLIFOS = {
  'ν':'v','υ':'u','ο':'o','ρ':'p','α':'a','ι':'i','κ':'k','τ':'t','χ':'x','ε':'e','η':'n','μ':'u',
  'Α':'A','Β':'B','Ε':'E','Ζ':'Z','Η':'H','Ι':'I','Κ':'K','Μ':'M','Ν':'N','Ο':'O','Ρ':'P','Τ':'T','Υ':'Y','Χ':'X',
  'а':'a','е':'e','о':'o','р':'p','с':'c','у':'y','х':'x','з':'3','и':'u','л':'n','м':'m','п':'n',
  'А':'A','В':'B','Е':'E','К':'K','М':'M','Н':'H','О':'O','Р':'P','С':'C','Т':'T','Х':'X','У':'Y','Й':'N',
};
let texto = String(doc.text || '');
texto = texto.replace(/[Ͱ-ϿЀ-ӿ]/g, ch => HOMOGLIFOS[ch] || ch);
const total_paginas = (doc.pages || []).length;
if (!texto.trim()) throw new Error('OCR retornou texto vazio.');

// ─── Índice de tokens para o corretor de leitura ────────────────────────────
//
// Cada token do Document AI vem com caixa (boundingPoly normalizado), confiança
// e a posição no texto. Até aqui isso era descartado, e era a única informação
// do pipeline capaz de responder "onde na página está o trecho que pode ter sido
// lido errado" — que é o que permite mostrar ao usuário o recorte da palavra em
// vez de pedir que ele releia o documento inteiro.
//
// O índice não é para guardar: ele viaja fora de `result` no callback (por isso
// o app não o grava em stage_data), vira no máximo oito candidatos e morre. Por
// isso os nomes de campo são de uma letra — num documento de trinta faces são
// milhares de linhas, e `confianca` repetido custaria mais que o dado.
//
// O filtro corta o que nenhum detector do app usaria: sobra o que o próprio
// Document AI leu com pouca confiança e o que tem dígito (CPF, CNPJ, data,
// valor, área, número de ato). O teste do dígito é feito nas duas leituras
// possíveis de offset — o `textSegments` do Document AI é documentado como
// índice de caractere e na prática vem em bytes UTF-8, e aqui não há como saber
// qual é sem o texto do lado. Quem decide isso é o app (packages/revisao);
// daqui saem os offsets crus, como o Google os mandou.
const LIMITE_TOKENS = 20000;
const LIMITE_CONFIANCA = 0.9;
// Acima deste desvio da horizontal o token e carimbo, nao texto do cartorio.
// O corte fino, contra a mediana da pagina, e feito no app; aqui o numero serve
// so para nao deixar o carimbo de fora do indice.
const LIMITE_GIRO = 15;
const bytes = Buffer.from(texto, 'utf8');
const arredonda = (v, casas) => Number(v.toFixed(casas));

const MINIMO_PARA_MEDIANA = 20;

function mediana(valores) {
  if (valores.length === 0) return 0;
  const ordenado = [...valores].sort((a, b) => a - b);
  const meio = Math.floor(ordenado.length / 2);
  return ordenado.length % 2 ? ordenado[meio] : (ordenado[meio - 1] + ordenado[meio]) / 2;
}

// Inclinação da aresta superior do token (v0 -> v1): a direção em que a palavra
// corre. A caixa vem normalizada em 0..1 sobre largura e altura SEPARADAMENTE,
// o que distorce ângulo — numa A4, 45° reais não aparecem como 45°. Desfazer a
// normalização com a dimensão da página é o que torna o número comparável.
function anguloDoToken(vertices, larguraPt, alturaPt) {
  if (vertices.length < 2) return 0;
  const dx = ((Number(vertices[1].x) || 0) - (Number(vertices[0].x) || 0)) * larguraPt;
  const dy = ((Number(vertices[1].y) || 0) - (Number(vertices[0].y) || 0)) * alturaPt;
  if (dx === 0 && dy === 0) return 0;
  const graus = Math.abs((Math.atan2(dy, dx) * 180) / Math.PI);
  return graus > 90 ? 180 - graus : graus;
}

const tokens = [];
for (const [i, pagina] of (doc.pages || []).entries()) {
  const numero = pagina.pageNumber || i + 1;
  const dim = pagina.dimension || {};
  const larguraPt = Number(dim.width) || 1;
  const alturaPt = Number(dim.height) || 1;
  const daPagina = pagina.tokens || [];

  // Primeira passada: o ângulo do CORPO da página, medido sobre todos os tokens.
  //
  // Sobre todos, e não sobre os que serão emitidos, por uma razão prática: o
  // índice é filtrado (confiança baixa, dígito, girado), e o carimbo entra
  // sempre. Numa página de pouco texto o carimbo poderia ser a maioria do que é
  // emitido — e aí a mediana seria a dele, invertendo o filtro e mandando
  // remover o documento em vez do carimbo. Aqui isso não acontece: a régua sai
  // da população inteira, onde o carimbo é sempre minoria.
  const angulos = [];
  for (const token of daPagina) {
    const vs = (((token.layout || {}).boundingPoly || {}).normalizedVertices) || [];
    if (vs.length >= 3) angulos.push(anguloDoToken(vs, larguraPt, alturaPt));
  }
  // Página sem massa não tem mediana confiável; a horizontal é o padrão.
  const corpo = angulos.length >= MINIMO_PARA_MEDIANA ? mediana(angulos) : 0;

  // Segunda passada: o que vai no índice.
  for (const token of daPagina) {
    if (tokens.length >= LIMITE_TOKENS) break;

    const layout = token.layout || {};
    const seg = ((layout.textAnchor || {}).textSegments || [])[0];
    const vertices = ((layout.boundingPoly || {}).normalizedVertices) || [];
    if (!seg || vertices.length < 3) continue;

    const s = Number(seg.startIndex || 0);
    const e = Number(seg.endIndex || 0);
    if (!(e > s)) continue;

    const c = typeof layout.confidence === 'number' ? layout.confidence : 1;
    const temDigito =
      /[0-9]/.test(texto.slice(s, e)) || /[0-9]/.test(bytes.slice(s, e).toString('utf8'));

    // `a` sai como DESVIO EM RELAÇÃO AO CORPO DA PÁGINA, não à horizontal
    // absoluta: digitalização torta inclina o documento inteiro, e medir contra
    // a horizontal apagaria a página toda. Contra o corpo, a inclinação do
    // scanner vira o novo zero e só o carimbo destoa.
    const desvio = Math.round(Math.abs(anguloDoToken(vertices, larguraPt, alturaPt) - corpo));

    // O girado entra mesmo lido com confiança alta e sem dígito: é o app que
    // remove o carimbo do texto (packages/revisao/carimbo.ts), e ele só remove
    // o que recebe. São poucas palavras por página — o índice quase não cresce.
    const girado = desvio > LIMITE_GIRO;
    if (c >= LIMITE_CONFIANCA && !temDigito && !girado) continue;

    const xs = vertices.map((v) => Number(v.x) || 0);
    const ys = vertices.map((v) => Number(v.y) || 0);

    tokens.push({
      p: numero,
      b: [
        arredonda(Math.min(...xs), 4),
        arredonda(Math.min(...ys), 4),
        arredonda(Math.max(...xs), 4),
        arredonda(Math.max(...ys), 4),
      ],
      c: arredonda(c, 3),
      a: desvio,
      s,
      e,
    });
  }
}

return [{ json: { texto_ocr: texto, total_paginas, tokens } }];

// Extrai Selo Digital TJSP e CNM do texto do OCR — porta em JS puro (sem import,
// n8n Code node não linka pacotes do workspace) do que packages/autenticidade/src/
// ancoras.ts + luhn.ts + iso7064.ts fazem. Qualquer mudança de comportamento
// precisa ser feita nos dois lugares.
//
// Nunca lança: qualquer erro aqui vira ancoras: null, e o OCR segue normalmente
// para o Callback OCR — o verificador de autenticidade não bloqueia a leitura.

const texto = String($json.texto_ocr || '');

function extrairAncoras(texto) {
  const ALFABETO = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const N = ALFABETO.length;

  function valorDoCaractere(c) {
    const v = ALFABETO.indexOf(c.toUpperCase());
    if (v < 0) throw new Error('char fora do alfabeto');
    return v;
  }

  function calcularDvLuhnModN(payload) {
    let fator = 2, soma = 0;
    for (let i = payload.length - 1; i >= 0; i--) {
      let parcela = valorDoCaractere(payload[i]) * fator;
      parcela = Math.floor(parcela / N) + (parcela % N);
      soma += parcela;
      fator = fator === 2 ? 1 : 2;
    }
    const resto = soma % N;
    return ALFABETO[(N - resto) % N];
  }

  function luhnModNFecha(codigo) {
    if (codigo.length < 2) return false;
    try {
      return calcularDvLuhnModN(codigo.slice(0, -1)) === codigo.slice(-1).toUpperCase();
    } catch {
      return false;
    }
  }

  function modBigInt(numeroDecimal, modulo) {
    let resto = 0n;
    for (const c of numeroDecimal) resto = (resto * 10n + BigInt(c)) % modulo;
    return resto;
  }

  function iso7064Fecha(numeroCompleto) {
    if (!/^\d{3,}$/.test(numeroCompleto)) return false;
    return modBigInt(numeroCompleto, 97n) === 1n;
  }

  const CONFUSOES_OCR = {
    O: '0', '0': 'O', I: '1', '1': 'I', S: '5', '5': 'S',
    B: '8', '8': 'B', Z: '2', '2': 'Z', G: '6', '6': 'G',
  };

  function substituir(codigo, posicoes) {
    const chars = [...codigo];
    for (const { indice, caractere } of posicoes) chars[indice] = caractere;
    return chars.join('');
  }

  function variantesComCorrecao(codigo) {
    const posicoes = [...codigo]
      .map((c, indice) => ({ indice, alt: CONFUSOES_OCR[c.toUpperCase()] }))
      .filter((p) => p.alt);
    const variantes = [];
    for (const p of posicoes) variantes.push(substituir(codigo, [{ indice: p.indice, caractere: p.alt }]));
    for (let a = 0; a < posicoes.length; a++) {
      for (let b = a + 1; b < posicoes.length; b++) {
        variantes.push(
          substituir(codigo, [
            { indice: posicoes[a].indice, caractere: posicoes[a].alt },
            { indice: posicoes[b].indice, caractere: posicoes[b].alt },
          ]),
        );
      }
    }
    return variantes;
  }

  function tentarComCorrecaoDv(codigo, fecha) {
    if (fecha(codigo)) return { codigo, corrigido: false };
    for (const variante of variantesComCorrecao(codigo)) {
      if (fecha(variante)) return { codigo: variante, corrigido: true };
    }
    return null;
  }

  // ─── Selo TJSP ──────────────────────────────────────────────────────────
  const JANELA_ROTULO = 80;
  const ROTULO_SELO = /selo\s*digital|tjsp/gi;

  function candidatosProximosAoRotulo(texto, tamanho, rotulo) {
    const posicoesRotulo = [];
    for (const m of texto.matchAll(rotulo)) posicoesRotulo.push(m.index || 0);
    if (posicoesRotulo.length === 0) return [];
    const achados = [];
    const padrao = new RegExp(`[0-9A-Za-z]{${tamanho}}`, 'g');
    for (const m of texto.matchAll(padrao)) {
      const idx = m.index || 0;
      if (posicoesRotulo.some((p) => Math.abs(p - idx) <= JANELA_ROTULO)) achados.push(m[0]);
    }
    return achados;
  }

  function decomporSelo(codigo, corrigido, dvFecha) {
    return {
      codigo,
      cns: codigo.slice(0, 6),
      natureza: codigo.slice(6, 7),
      ato: codigo.slice(7, 9),
      infoAto: codigo.slice(9, 22),
      ano: codigo.slice(22, 24),
      dv: codigo.slice(24, 25),
      dvFecha,
      corrigidoPorDv: corrigido,
      origem: 'texto_ocr',
    };
  }

  function extrairSelo(texto) {
    const rotulados = candidatosProximosAoRotulo(texto, 25, ROTULO_SELO);
    for (const bruto of rotulados) {
      const codigo = bruto.toUpperCase();
      const r = tentarComCorrecaoDv(codigo, luhnModNFecha);
      if (r) return decomporSelo(r.codigo, r.corrigido, true);
    }
    if (rotulados.length > 0) return decomporSelo(rotulados[0].toUpperCase(), false, false);

    for (const m of texto.matchAll(/\b[0-9A-Za-z]{25}\b/g)) {
      const codigo = m[0].toUpperCase();
      const r = tentarComCorrecaoDv(codigo, luhnModNFecha);
      if (r) return decomporSelo(r.codigo, r.corrigido, true);
    }
    return null;
  }

  // ─── CNM ────────────────────────────────────────────────────────────────
  const CNM_PONTUADO = /\b(\d{5})\.(\d)\.(\d{7})-(\d{2})\b/g;
  const CNM_SEM_PONTUACAO = /\b\d{15}\b/g;

  function decomporCnm(cns, livro, numeroOrdem, dv, corrigido, dvFecha) {
    return {
      codigo: `${cns}.${livro}.${numeroOrdem}-${dv}`,
      cns,
      livro,
      numeroOrdem,
      dv,
      dvFecha,
      livroEhRegistroGeral: livro === '2',
      corrigidoPorDv: corrigido,
      origem: 'texto_ocr',
    };
  }

  function extrairCnm(texto) {
    for (const m of texto.matchAll(CNM_PONTUADO)) {
      const [, cns, livro, numeroOrdem, dv] = m;
      const completo = cns + livro + numeroOrdem + dv;
      if (iso7064Fecha(completo)) return decomporCnm(cns, livro, numeroOrdem, dv, false, true);
      return decomporCnm(cns, livro, numeroOrdem, dv, false, false);
    }
    for (const m of texto.matchAll(CNM_SEM_PONTUACAO)) {
      const bloco = m[0];
      const base = bloco.slice(0, 13);
      const dv = bloco.slice(13, 15);
      if (iso7064Fecha(base + dv)) {
        return decomporCnm(base.slice(0, 5), base.slice(5, 6), base.slice(6, 13), dv, false, true);
      }
    }
    return null;
  }

  return { selo: extrairSelo(texto), cnm: extrairCnm(texto) };
}

let ancoras = { selo: null, cnm: null };
try {
  ancoras = extrairAncoras(texto);
} catch (e) {
  // nunca bloqueia o OCR por causa disto
  ancoras = { selo: null, cnm: null };
}

return [{ json: { ...$json, ancoras } }];

const item = $input.first().json;
const err = (item.error && typeof item.error === 'object') ? item.error : {};
const partes = [];
const msg = err.message || item.error || item.message;
if (msg) partes.push(String(typeof msg === 'object' ? JSON.stringify(msg) : msg));
if (err.description && !partes.includes(String(err.description))) partes.push(String(err.description));
const texto = partes.join(' — ') || 'Falha no OCR';
return [{ json: { errorMessage: texto.slice(0, 500) } }];

// $binary.data.data traz só o placeholder 'filesystem-v2' quando o binário vai
// para o filesystem — ler via helpers garante o conteúdo real em base64
const buf = await helpers.getBinaryDataBuffer(0, 'data');
if (!buf || buf.length < 100) throw new Error('PDF vazio ou não baixado.');
return [{ json: { ...$input.first().json, pdfBase64: buf.toString('base64') } }];
